function makePlanner(buildOrder, priorities, cfg) {
  const clamp=(x,a,b)=>Math.min(b,Math.max(x,a));
  const types=["cannon","flak","frost"];
  let wave=0, airLoad=0.13;
  return {
    plan(s) {
      wave=s.wave;
      const preview=s.nextWave.filter(k=>k==="wisp").length/s.nextWave.length;
      airLoad=.52*airLoad+.48*preview;
      let danger=0;
      for(const e of s.enemies) if(e.air) danger=Math.max(danger,(e.hp/e.maxHp)*(1-e.remaining/2800));
      const bias=clamp((airLoad-.13)*cfg[4]+(danger-.36)*cfg[5],-16,24);
      const actions=[], tiers=s.slots.map(p=>p.turret?p.turret.tier:0);
      let gold=s.gold;
      for(let i=0;i<32;i++) {
        let best=-1, slot=-1, price=0;
        for(let j=0;j<16;j++) {
          const tier=tiers[j];
          if(tier===3) continue;
          const cost=[90,80,70][buildOrder[j]]*Math.max(1,tier);
          const rank=priorities[tier*16+j]+(wave>7&&buildOrder[j]===1?bias:0);
          if(rank>best){best=rank;slot=j;price=cost;}
        }
        if(slot<0||price>gold) break;
        actions.push(tiers[slot]?{op:"upgrade",slot}:{op:"build",slot,type:types[buildOrder[slot]]});
        tiers[slot]++; gold-=price;
      }
      return actions;
    },
    target(t,cs) {
      if(t.type==="frost") {
        let id=cs[0].id,best=-Infinity;
        for(const e of cs) {
          const value=(e.air?2.4:1)*(e.slowed?0.10:1)*(e.hp/e.maxHp+.6)*(1+1.8/(1+e.remaining/900))*(e.speed/10);
          if(value>best){best=value;id=e.id;}
        }
        return id;
      }
      const flak=t.type==="flak", radius2=flak?4900:8100;
      const damage=(flak?[40,64,102]:[60,96,153])[t.tier-1];
      let best=-1, id=cs[0].id;
      const values=cs.map(e=>{
        const d=Math.max(1,damage-e.armor);
        const urgency=1/(1+e.remaining/(e.speed*cfg[0]));
        const importance=(1+cfg[1]*urgency*urgency + cfg[2]*(e.type==="mender")) * (1+(wave>20?cfg[3]:.1)*(e.type==="runner"));
        return importance*(Math.min(e.hp,d)+(e.hp<=d?0.22*d:0));
      });
      for(let i=0;i<cs.length;i++) {
        const a=cs[i]; let score=0;
        for(let j=0;j<cs.length;j++) {
          const b=cs[j];
          if((a.x-b.x)**2+(a.y-b.y)**2<=radius2) score+=values[j];
        }
        if(score>best) {best=score;id=a.id;}
      }
      return id;
    }
  };
}

