/bin/zsh -lc "printf '%s\\n' '  // Compare late-game refits against the current board over a short, four-tick forecast.
  const forecastStats={bolt:[50,26,8,300,0],cannon:[90,60,24,260,90],frost:[70,10,12,240,0],lance:[120,180,36,360,0],flak:[80,40,10,320,70]};
  const route=(points)=>points.slice(1).map(([x,y],i)=>[points[i][0]*100+50,points[i][1]*100+50,Math.sign(x-points[i][0]),Math.sign(y-points[i][1]),(Math.abs(x-points[i][0])+Math.abs(y-points[i][1]))*100]);
  const ground=route([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]);
  const air=route([[0,6],[21,6],[21,11],[23,11]]);
  function forecast(s,board) {
    const horizon=144,step=4;
    let lost=0,units=s.enemies.map(e=>({...e,slowed:e.slowed?15:0,leak:e.type===\"brute\"?3:e.air||e.type===\"mender\"||e.type===\"splitter\"?2:1,route:e.air?air:ground,seg:0}));
    const towers=board.filter(Boolean).map(t=>{
      const [,d,period,r,splash]=forecastStats[t.type];
      return {...t,cd:(t.slot%3)*4,damage:t.tier===1?d:t.tier===2?Math.floor(d*1.6):Math.floor(Math.floor(d*1.6)*1.6),period,splash,r2:(r+30*(t.tier-1))**2};
    });
    for(const e of units){
      let done=(e.air?2800:4600)-e.remaining;
      while(e.seg<e.route.length-1&&done>=e.route[e.seg][4])done-=e.route[e.seg++][4];
      e.along=done;
    }
    let nextId=100000;
    for(let dt=0;dt<horizon;dt+=step) {
      for(const e of units) {
        const speed=e.slowed>0?Math.floor(.6*e.speed):e.speed,dist=speed*step;
        e.slowed=Math.max(0,e.slowed-step);e.remaining-=dist;e.along+=dist;
        if(e.remaining<=0){lost+=e.leak*(1-.35*dt/horizon);continue;}
        while(e.seg<e.route.length-1&&e.along>=e.route[e.seg][4])e.along-=e.route[e.seg++][4];
        const p=e.route[e.seg];e.x=p[0]+e.along*p[2];e.y=p[1]+e.along*p[3];
      }
      units=units.filter(e=>e.remaining>0);
      if(dt%20===0)for(const m of units)if(m.type===\"mender\")for(const e of units)if((e.x-m.x)**2+(e.y-m.y)**2<=22500)e.hp=Math.min(e.maxHp,e.hp+Math.floor(e.maxHp*.08));
      for(const t of towers){
        t.cd-=step;if(t.cd>0)continue;
        const cs=units.filter(e=>(e.air?t.type"'!=="lance"&&t.type!=="cannon":t.type!=="flak") && (t.x-e.x)**2+(t.y-e.y)**2<=t.r2);
        if(!cs.length){t.cd=0;continue;}
        const id=chooseTarget(t,cs),hit=cs.find(e=>e.id===id);
        t.cd+=t.period;
        const victims=t.splash?units.filter(e=>e.air===hit.air&&(e.x-hit.x)**2+(e.y-hit.y)**2<=t.splash*t.splash):[hit];
        for(const e of victims) {
          e.hp-=Math.max(1,t.damage-(t.type==="lance"?0:e.armor));
          if(t.type==="frost")e.slowed=30;
          if(e.hp<=0&&e.type==="splitter")for(let i=0;i<3;i++){const hp=Math.max(1,Math.floor(e.maxHp/4));units.push({...e,id:nextId++,type:"splitling",speed:12,slowed:0,hp,maxHp:hp,leak:1});}
        }
        if(victims.some(e=>e.hp<=0))units=units.filter(e=>e.hp>0);
      }
    }
    for(const e of units){
      const until=e.remaining/e.speed;
      lost+=e.leak*(.15+.85*e.hp/e.maxHp)*(.55*Math.exp(-until/69)+.035);
    }
    return lost;
  }
  function refit(s,actions) {
    if(s.wave<36||s.enemies.length>420)return actions;
    let wallet=s.gold;
    const board=s.slots.map(p=>p.turret?{...p.turret,x:p.x,y:p.y,slot:p.slot}:null);
    for(const a of actions){
      const p=s.slots[a.slot];
      if(a.op==="build"){const cost=forecastStats[a.type][0];wallet-=cost;board[a.slot]={slot:a.slot,x:p.x,y:p.y,type:a.type,tier:1,spent:cost};}
      else {const t=board[a.slot],cost=t.tier*forecastStats[t.type][0];wallet-=cost;t.tier++;t.spent+=cost;}
    }
    const first=forecast(s,board);let best=first,bundle=null;
    if(first<.6)return actions;
    for(const slot of [5,6,7,10,11,12,13,14,15]) {
      const old=board[slot];if(!old)continue;
      const refund=Math.floor(.7*old.spent),budget=wallet+refund;
      const options=slot>=12&&slot<=14?["flak","cannon","frost","lance","bolt"]:["flak","cannon"];
      for(const type of options) {
        if(type===old.type)continue;
        const c=forecastStats[type][0],tier=budget>=4*c?3:budget>=2*c?2:budget>=c?1:0;
        if(tier<2)continue;
        const spent=c*(tier===3?4:2);
        board[slot]={...old,type,tier,spent};
        const value=forecast(s,board)+.40+Math.max(0,spent-refund)*.002;
        if(value<best){
          best=value;bundle=[{op:"sell",slot},{op:"build",type,slot}];
          for(let i=1;i<tier;i++)bundle.push({op:"upgrade",slot});
        }
      }
      board[slot]=old;
    }
    return bundle?actions.concat(bundle):actions;
  }
